import { useState, useCallback, useEffect } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import {
  FiGrid, FiList, FiZap, FiPlus, FiMenu, FiX, FiDollarSign, FiSun, FiMoon
} from 'react-icons/fi';
import { ExpenseProvider, useExpense } from './context/ExpenseContext';
import Dashboard from './components/Dashboard';
import TransactionList from './components/TransactionList';
import Insights from './components/Insights';
import AddTransaction from './components/AddTransaction';
import Toast from './components/Toast';
import { formatCurrency } from './utils/helpers';
import './App.css';

function AppContent() {
  const [page, setPage] = useState('dashboard');
  const [showAddTx, setShowAddTx] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [toasts, setToasts] = useState([]);
  const [theme, setTheme] = useState('brutal');

  const { dispatch, region } = useExpense();

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
  }, [theme]);

  const addToast = useCallback((toast) => {
    const id = Date.now();
    setToasts(prev => [...prev, { ...toast, id }]);
  }, []);

  const removeToast = useCallback((id) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  }, []);


  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: FiGrid },
    { id: 'transactions', label: 'Transactions', icon: FiList },
    { id: 'insights', label: 'Insights', icon: FiZap },
  ];

  return (
    <div className="app">
      {/* Mobile Header */}
      <div className="mobile-header">
        <button className="mobile-menu-btn" onClick={() => setSidebarOpen(true)}>
          <FiMenu />
        </button>
        <div style={{ fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: '1.1rem' }}>
          SpendWise
        </div>
        <button
          className="mobile-menu-btn"
          onClick={() => setShowAddTx(true)}
        >
          <FiPlus />
        </button>
      </div>

      {/* Sidebar Overlay (mobile) */}
      <div
        className={`sidebar-overlay ${sidebarOpen ? 'visible' : ''}`}
        onClick={() => setSidebarOpen(false)}
      />

      {/* Sidebar */}
      <nav className={`sidebar ${sidebarOpen ? 'open' : ''}`}>
        <div className="sidebar-brand">
          <div className="sidebar-brand-icon">
            <FiDollarSign />
          </div>
          <div>
            <h1>SpendWise</h1>
            <span>Smart Finance Tracker</span>
          </div>
        </div>

        <div className="sidebar-nav">
          {navItems.map(item => (
            <button
              key={item.id}
              className={`sidebar-link ${page === item.id ? 'active' : ''}`}
              onClick={() => { setPage(item.id); setSidebarOpen(false); }}
            >
              <item.icon />
              {item.label}
            </button>
          ))}
        </div>

        <div className="sidebar-footer" style={{ marginTop: 'auto', paddingTop: '20px', borderTop: '1px solid var(--border-subtle)' }}>
          <button 
            className="sidebar-link" 
            onClick={() => setTheme(theme === 'brutal' ? 'glass' : 'brutal')}
            style={{ justifyContent: 'center', padding: '12px', fontSize: '1.25rem', width: '48px', height: '48px', margin: '0 auto', display: 'flex', alignItems: 'center', overflow: 'hidden' }}
            title={theme === 'brutal' ? 'Switch to Dark Mode' : 'Switch to Light Mode'}
          >
            <AnimatePresence mode="wait">
              <motion.div
                key={theme}
                initial={{ y: -20, opacity: 0, rotate: -90 }}
                animate={{ y: 0, opacity: 1, rotate: 0 }}
                exit={{ y: 20, opacity: 0, rotate: 90 }}
                transition={{ duration: 0.2 }}
                style={{ display: 'flex' }}
              >
                {theme === 'brutal' ? <FiMoon /> : <FiSun />}
              </motion.div>
            </AnimatePresence>
          </button>
        </div>
      </nav>

      {/* Main Content */}
      <main className="main-content">
        <AnimatePresence mode="wait">
          {page === 'dashboard' && <Dashboard key="dashboard" />}
          {page === 'transactions' && <TransactionList key="transactions" />}
          {page === 'insights' && <Insights key="insights" />}
        </AnimatePresence>
      </main>

      {/* FAB */}
      <motion.button
        className="fab"
        onClick={() => setShowAddTx(true)}
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.9 }}
        initial={{ scale: 0 }}
        animate={{ scale: 1 }}
        transition={{ type: 'spring', stiffness: 300, delay: 0.5 }}
      >
        <FiPlus />
      </motion.button>

      {/* Add Transaction Modal */}
      <AnimatePresence>
        {showAddTx && (
          <AddTransaction
            onClose={() => setShowAddTx(false)}
            onToast={addToast}
          />
        )}
      </AnimatePresence>

      {/* Toasts */}
      <Toast toasts={toasts} removeToast={removeToast} />
    </div>
  );
}

export default function App() {
  return (
    <ExpenseProvider>
      <AppContent />
    </ExpenseProvider>
  );
}

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { FiX, FiArrowDown, FiArrowUp, FiTerminal, FiAlertOctagon, FiShield, FiTarget } from 'react-icons/fi';
import { useExpense } from '../context/ExpenseContext';
import { EXPENSE_CATEGORIES, INCOME_CATEGORIES, SAVINGS_CATEGORIES } from '../utils/categories';
import { formatCurrency } from '../utils/helpers';

export default function AddTransaction({ onClose, onToast }) {
  const { dispatch, limits, periods, savingsGoal, balance, region } = useExpense();
  const [type, setType] = useState('expense');
  const [amount, setAmount] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [limitWarning, setLimitWarning] = useState(null);

  const categories = type === 'expense' ? EXPENSE_CATEGORIES : type === 'savings' ? SAVINGS_CATEGORIES : INCOME_CATEGORIES;

  const selectedCat = categories.find(c => c.key === category);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (type === 'goals') return; // Goals are saved onChange

    if (!amount || !category) return;

    const numAmount = parseFloat(amount);
    if (isNaN(numAmount) || numAmount <= 0) return;

    if (type === 'expense') {
      let limitMsg = null;
      if (balance < numAmount) {
        limitMsg = `Insufficient funds! This expense is greater than your total balance of ${formatCurrency(balance, region)}.`;
      } else if (limits.daily > 0 && periods.daily + numAmount > limits.daily) {
        limitMsg = `This expense exceeds your daily limit of ${formatCurrency(limits.daily, region)}.`;
      } else if (limits.weekly > 0 && periods.weekly + numAmount > limits.weekly) {
        limitMsg = `This expense exceeds your weekly limit of ${formatCurrency(limits.weekly, region)}.`;
      } else if (limits.monthly > 0 && periods.monthly + numAmount > limits.monthly) {
        limitMsg = `This expense exceeds your monthly limit of ${formatCurrency(limits.monthly, region)}.`;
      } else if (savingsGoal > 0 && balance - numAmount < savingsGoal) {
        limitMsg = `This expense drops your balance below your savings goal of ${formatCurrency(savingsGoal, region)}.`;
      }

      if (limitMsg) {
        setLimitWarning(limitMsg);
        return;
      }
    }

    finalizeSubmit(numAmount);
  };

  const finalizeSubmit = (numAmount) => {
    let label = selectedCat?.label ?? category;
    if ((category === 'other_expense' || category === 'other_income') && description.trim()) {
      label = description.trim();
    }

    dispatch({
      type: 'ADD_TRANSACTION',
      payload: {
        type,
        amount: numAmount,
        description: label,
        category,
        date,
      },
    });

    onToast?.({
      type: type === 'savings' ? 'info' : type === 'expense' ? 'warning' : 'success',
      title: type === 'savings' ? 'Savings Logged' : type === 'expense' ? 'Expense Added' : 'Income Added',
      message: `${label} ΓÇö ${type === 'expense' ? 'ΓêÆ' : '+'}Γé╣${numAmount.toFixed(2)}`,
    });

    onClose();
  };

  const isOther = category === 'other_expense' || category === 'other_income';
  const isDescriptionValid = !isOther || (isOther && description.trim() !== '');
  const isValid = amount && category && parseFloat(amount) > 0 && isDescriptionValid;


  return (
    <AnimatePresence>
      <motion.div
        className="add-tx-overlay"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        onClick={onClose}
      >
        <motion.div
          className="add-tx-modal"
          initial={{ opacity: 0, scale: 0.92, y: 30 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.92, y: 30 }}
          transition={{ type: 'spring', stiffness: 300, damping: 25 }}
          onClick={e => e.stopPropagation()}
        >
          <div className="add-tx-header">
            <h3>Add Transaction</h3>
            <button className="add-tx-close" onClick={onClose}>
              <FiX />
            </button>
          </div>

          <AnimatePresence mode="wait">
            {limitWarning ? (
              <motion.div
                key="warning"
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.95 }}
                style={{ textAlign: 'center', padding: '20px 0' }}
              >
                <div style={{ fontSize: '3rem', color: 'var(--accent-red)', marginBottom: '16px' }}>
                  <FiAlertOctagon />
                </div>
                <h3 style={{ marginBottom: '12px', color: 'var(--accent-red)' }}>Limit Exceeded</h3>
                <p style={{ color: 'var(--text-secondary)', marginBottom: '24px', lineHeight: 1.5 }}>
                  {limitWarning}<br/><br/>
                  <strong>Please make other arrangements or adjust your goals to proceed.</strong>
                </p>
                <button
                  type="button"
                  className="form-submit"
                  style={{ background: 'var(--bg-input)', color: 'var(--text-primary)', boxShadow: 'none' }}
                  onClick={() => setLimitWarning(null)}
                >
                  Got It
                </button>
              </motion.div>
            ) : (
              <motion.form 
                key="form"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                onSubmit={handleSubmit}
              >
                {/* Type Toggle */}
            <div className="form-type-toggle">
                <button
                  type="button"
                  className={`type-btn ${type === 'expense' ? 'active-expense' : ''}`}
                  onClick={() => { setType('expense'); setCategory(''); setDescription(''); }}
                >
                  <FiArrowDown /> Expense
                </button>
                <button
                  type="button"
                  className={`type-btn ${type === 'income' ? 'active-income' : ''}`}
                  onClick={() => { setType('income'); setCategory(''); setDescription(''); }}
                >
                  <FiArrowUp /> Income
                </button>
                <button
                  type="button"
                  className={`type-btn ${type === 'savings' ? 'active-savings' : ''}`}
                  onClick={() => { setType('savings'); setCategory(''); setDescription(''); }}
                >
                  <FiShield /> Savings
                </button>
                <button
                  type="button"
                  className={`type-btn ${type === 'goals' ? 'active-goals' : ''}`}
                  onClick={() => { setType('goals'); setCategory(''); setDescription(''); }}
                >
                  <FiTarget /> Goals
                </button>
            </div>

            {type === 'goals' ? (
              <motion.div
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0 }}
                className="goals-form-section"
              >
                <div className="form-group" style={{ marginBottom: '16px' }}>
                  <label>Savings Goal ({region.code})</label>
                  <input
                    type="number"
                    className="form-input"
                    placeholder="e.g. 5000"
                    value={savingsGoal || ''}
                    onChange={e => {
                      const val = parseFloat(e.target.value);
                      if (val >= 0 || e.target.value === '') {
                        dispatch({ type: 'SET_SAVINGS_GOAL', payload: val || 0 });
                      }
                    }}
                    min="0"
                  />
                </div>
                <div className="form-group" style={{ marginBottom: '16px' }}>
                  <label>Daily Limit ({region.code})</label>
                  <input
                    type="number"
                    className="form-input"
                    placeholder="e.g. 50"
                    value={limits.daily || ''}
                    onChange={e => {
                      const val = parseFloat(e.target.value);
                      if (val >= 0 || e.target.value === '') {
                        dispatch({ type: 'SET_LIMITS', payload: { daily: val || 0 } });
                      }
                    }}
                    min="0"
                  />
                </div>
                <div className="form-group" style={{ marginBottom: '16px' }}>
                  <label>Weekly Limit ({region.code})</label>
                  <input
                    type="number"
                    className="form-input"
                    placeholder="e.g. 350"
                    value={limits.weekly || ''}
                    onChange={e => {
                      const val = parseFloat(e.target.value);
                      if (val >= 0 || e.target.value === '') {
                        dispatch({ type: 'SET_LIMITS', payload: { weekly: val || 0 } });
                      }
                    }}
                    min="0"
                  />
                </div>
                <div className="form-group" style={{ marginBottom: '24px' }}>
                  <label>Monthly Limit ({region.code})</label>
                  <input
                    type="number"
                    className="form-input"
                    placeholder="e.g. 1500"
                    value={limits.monthly || ''}
                    onChange={e => {
                      const val = parseFloat(e.target.value);
                      if (val >= 0 || e.target.value === '') {
                        dispatch({ type: 'SET_LIMITS', payload: { monthly: val || 0 } });
                      }
                    }}
                    min="0"
                  />
                </div>
                <motion.button
                  type="button"
                  className="form-submit"
                  onClick={() => {
                    onToast?.({ type: 'success', title: 'Goals Saved', message: 'Your financial goals and limits have been updated.' });
                    onClose();
                  }}
                  whileTap={{ scale: 0.98 }}
                >
                  Save Goals & Limits
                </motion.button>
              </motion.div>
            ) : (
              <>

            {/* Amount */}
            <div className="form-group">
              <label>Amount</label>
              <input
                type="number"
                className="form-input"
                placeholder="0.00"
                value={amount}
                onChange={e => {
                  const val = e.target.value;
                  if (val === '' || parseFloat(val) >= 0) {
                    setAmount(val);
                  }
                }}
                min="0"
                step="0.01"
                autoFocus
              />
            </div>



            {/* Date */}
            <div className="form-group">
              <label>Date</label>
              <input
                type="date"
                className="form-input"
                value={date}
                onChange={e => setDate(e.target.value)}
              />
            </div>

            {/* Category Grid */}
            <div className="form-group">
              <label>Category</label>
              <div className="category-grid">
                {categories.map(cat => {
                  const Icon = cat.icon;
                  return (
                    <motion.button
                      key={cat.key}
                      type="button"
                      className={`category-chip ${category === cat.key ? 'selected' : ''}`}
                      onClick={() => setCategory(cat.key)}
                      whileTap={{ scale: 0.95 }}
                    >
                      <Icon style={{ color: cat.color }} />
                      {cat.label}
                    </motion.button>
                  );
                })}
              </div>
            </div>

            {/* Description (Only for Other) */}
            <AnimatePresence>
              {(category === 'other_expense' || category === 'other_income') && (
                <motion.div
                  initial={{ opacity: 0, height: 0, marginTop: 0 }}
                  animate={{ opacity: 1, height: 'auto', marginTop: 16 }}
                  exit={{ opacity: 0, height: 0, marginTop: 0, overflow: 'hidden' }}
                  className="form-group"
                >
                  <label>Description (Required)</label>
                  <input
                    type="text"
                    className="form-input"
                    placeholder="What was this for?"
                    value={description}
                    onChange={e => setDescription(e.target.value)}
                  />
                </motion.div>
              )}
            </AnimatePresence>

            {/* Submit */}
            <motion.button
              type="submit"
              className="form-submit"
              disabled={!isValid}
              whileTap={{ scale: 0.98 }}
            >
              {type === 'expense' ? 'Add Expense' : type === 'income' ? 'Add Income' : 'Deposit Savings'}
            </motion.button>
              </>
            )}
            </motion.form>
            )}
          </AnimatePresence>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
}

import { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  LineChart, Line, XAxis, YAxis, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, CartesianGrid, BarChart, Bar
} from 'recharts';
import { FiTrendingUp, FiTrendingDown, FiDollarSign, FiTarget, FiAlertTriangle, FiInfo, FiCheckCircle, FiZap } from 'react-icons/fi';
import { useExpense } from '../context/ExpenseContext';
import { formatCurrency, getChartData } from '../utils/helpers';
import CATEGORIES from '../utils/categories';

const containerVariants = {
  hidden: { opacity: 0 },
  show: { opacity: 1, transition: { staggerChildren: 0.06 } },
};

const itemVariants = {
  hidden: { opacity: 0, y: 20 },
  show: { opacity: 1, y: 0, transition: { duration: 0.4, ease: [0.25, 0.46, 0.45, 0.94] } },
};

const INSIGHT_ICONS = {
  warning: FiAlertTriangle,
  danger: FiAlertTriangle,
  tip: FiZap,
  info: FiInfo,
  success: FiCheckCircle,
};

function CustomTooltip({ active, payload, label, region }) {
  if (!active || !payload?.length) return null;
  return (
    <div style={{
      background: 'rgba(18, 18, 26, 0.95)',
      border: '1px solid rgba(255,255,255,0.1)',
      borderRadius: 12,
      padding: '12px 16px',
      backdropFilter: 'blur(10px)',
    }}>
      <p style={{ fontSize: '0.8rem', color: '#94a3b8', marginBottom: 6 }}>{label}</p>
      {payload.map((entry, i) => (
        <p key={i} style={{ fontSize: '0.85rem', color: entry.color, fontWeight: 600 }}>
          {entry.name}: {formatCurrency(entry.value, region)}
        </p>
      ))}
    </div>
  );
}

export default function Dashboard() {
  const { transactions, totalIncome, totalExpenses, balance, savedAmount, savingsProgress, analysis, region } = useExpense();
  const [chartMode, setChartMode] = useState('week');
  const [catChartMode, setCatChartMode] = useState('pie');

  const chartData = useMemo(() =>
    getChartData(transactions, chartMode),
    [transactions, chartMode]
  );

  const categoryData = useMemo(() => {
    const entries = Object.entries(analysis.categoryTotals)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 6);
    const total = entries.reduce((s, [, v]) => s + v, 0);
    return entries.map(([key, value]) => ({
      name: CATEGORIES[key]?.label || key,
      value,
      color: CATEGORIES[key]?.color || '#94a3b8',
      percent: total > 0 ? Math.round((value / total) * 100) : 0,
    }));
  }, [analysis.categoryTotals]);

  const stats = [
    {
      label: 'Balance',
      value: formatCurrency(balance, region),
      icon: FiDollarSign,
      bg: 'var(--accent-primary-glow)',
      color: 'var(--accent-primary)',
      change: null,
    },
    {
      label: 'Income',
      value: formatCurrency(totalIncome, region),
      icon: FiTrendingUp,
      bg: 'var(--accent-green-dim)',
      color: 'var(--accent-green)',
      change: null,
    },
    {
      label: 'Expenses',
      value: formatCurrency(totalExpenses, region),
      icon: FiTrendingDown,
      bg: 'var(--accent-red-dim)',
      color: 'var(--accent-red)',
      change: analysis.percentChange !== 0 ? `${analysis.percentChange > 0 ? '+' : ''}${Math.round(analysis.percentChange)}% vs last month` : null,
      changeColor: analysis.percentChange > 0 ? 'var(--accent-red)' : 'var(--accent-green)',
    },
    {
      label: 'Total Saved',
      value: formatCurrency(savedAmount, region),
      icon: FiCheckCircle,
      bg: 'var(--accent-blue-dim)',
      color: 'var(--accent-blue)',
      change: savingsProgress > 0 ? `${Math.round(savingsProgress)}% of goal` : null,
      changeColor: savingsProgress >= 100 ? 'var(--accent-green)' : 'var(--accent-primary)',
    },
  ];

  const allInsights = [...analysis.alerts, ...analysis.tips];

  return (
    <motion.div variants={containerVariants} initial="hidden" animate="show">
      <motion.div variants={itemVariants} className="page-header">
        <h2>Dashboard</h2>
        <p>Track your finances, spend smarter</p>
      </motion.div>

      {/* Stats Cards */}
      <motion.div variants={itemVariants} className="stats-grid">
        {stats.map((stat, i) => (
          <motion.div
            key={i}
            className="stat-card"
            whileHover={{ scale: 1.02 }}
            transition={{ type: 'spring', stiffness: 300 }}
          >
            <div className="stat-card-icon" style={{ background: stat.bg, color: stat.color }}>
              <stat.icon />
            </div>
            <div className="stat-card-label">{stat.label}</div>
            <div className="stat-card-value" style={{ color: stat.color }}>{stat.value}</div>
            {stat.change && (
              <div className="stat-card-change" style={{ color: stat.changeColor }}>
                {stat.change}
              </div>
            )}
          </motion.div>
        ))}
      </motion.div>

      {/* Smart Insights */}
      {allInsights.length > 0 && (
        <motion.div variants={itemVariants} className="insights-section">
          <h3>
            <FiZap style={{ color: 'var(--accent-orange)' }} />
            Smart Insights
          </h3>
          <div className="insights-grid">
            <AnimatePresence>
              {allInsights.map((insight, i) => {
                const Icon = INSIGHT_ICONS[insight.type] || FiInfo;
                return (
                  <motion.div
                    key={i}
                    className={`insight-card ${insight.type}`}
                    initial={{ opacity: 0, scale: 0.95 }}
                    animate={{ opacity: 1, scale: 1 }}
                    exit={{ opacity: 0, scale: 0.95 }}
                    transition={{ delay: i * 0.05 }}
                  >
                    <div className="insight-icon">
                      <Icon />
                    </div>
                    <div className="insight-content">
                      <h4>{insight.title}</h4>
                      <p>{insight.message}</p>
                    </div>
                  </motion.div>
                );
              })}
            </AnimatePresence>
          </div>
        </motion.div>
      )}

      {/* Charts */}
      <motion.div variants={itemVariants} className="charts-grid">
        <div className="chart-card">
          <div className="chart-card-header">
            <h3>Spending Overview</h3>
            <div className="chart-toggle">
              <button className={chartMode === 'week' ? 'active' : ''} onClick={() => setChartMode('week')}>1W</button>
              <button className={chartMode === 'month' ? 'active' : ''} onClick={() => setChartMode('month')}>1M</button>
              <button className={chartMode === 'year' ? 'active' : ''} onClick={() => setChartMode('year')}>1Y</button>
              <button className={chartMode === 'all' ? 'active' : ''} onClick={() => setChartMode('all')}>All</button>
            </div>
          </div>
          <ResponsiveContainer width="100%" height={220}>
            <LineChart data={chartData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="rgba(255,255,255,0.05)" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: 'var(--text-muted)', fontSize: 11 }} dy={10} />
              <YAxis axisLine={false} tickLine={false} tick={{ fill: 'var(--text-muted)', fontSize: 11 }} tickFormatter={(val) => val >= 1000 ? `${(val/1000).toFixed(1)}k` : val} />
              <Tooltip content={<CustomTooltip region={region} />} cursor={{ stroke: 'var(--border-light)', strokeWidth: 1, strokeDasharray: '4 4' }} />
              <Line type="monotone" dataKey="income" stroke="var(--accent-green)" strokeWidth={3} dot={{ r: 4, strokeWidth: 2, fill: 'var(--bg-card)' }} activeDot={{ r: 6 }} name="Income" />
